// FinanceServiceServer is the server API for FinanceService service.
// All implementations must embed UnimplementedFinanceServiceServer
// for forward compatibility.
type FinanceServiceServer interface {
	// ==================== Company Settings ====================
	GetCompanySettings(context.Context, *GetCompanySettingsRequest) (*GetCompanySettingsResponse, error)
	UpdateCompanySettings(context.Context, *UpdateCompanySettingsRequest) (*UpdateCompanySettingsResponse, error)
	// ==================== Quotes ====================
	CreateQuote(context.Context, *CreateQuoteRequest) (*CreateQuoteResponse, error)
	GetQuote(context.Context, *GetQuoteRequest) (*GetQuoteResponse, error)
	ListQuotes(context.Context, *ListQuotesRequest) (*ListQuotesResponse, error)
	UpdateQuote(context.Context, *UpdateQuoteRequest) (*UpdateQuoteResponse, error)
	DeleteQuote(context.Context, *DeleteQuoteRequest) (*DeleteQuoteResponse, error)
	SendQuote(context.Context, *SendQuoteRequest) (*SendQuoteResponse, error)
	AcceptQuote(context.Context, *AcceptQuoteRequest) (*AcceptQuoteResponse, error)
	RejectQuote(context.Context, *RejectQuoteRequest) (*RejectQuoteResponse, error)
	ExpireQuote(context.Context, *ExpireQuoteRequest) (*ExpireQuoteResponse, error)
	ConvertQuoteToInvoice(context.Context, *ConvertQuoteToInvoiceRequest) (*ConvertQuoteToInvoiceResponse, error)
	// ==================== Invoices ====================
	CreateInvoice(context.Context, *CreateInvoiceRequest) (*CreateInvoiceResponse, error)
	GetInvoice(context.Context, *GetInvoiceRequest) (*GetInvoiceResponse, error)
	ListInvoices(context.Context, *ListInvoicesRequest) (*ListInvoicesResponse, error)
	UpdateInvoice(context.Context, *UpdateInvoiceRequest) (*UpdateInvoiceResponse, error)
	SendInvoice(context.Context, *SendInvoiceRequest) (*SendInvoiceResponse, error)
	MarkInvoicePaid(context.Context, *MarkInvoicePaidRequest) (*MarkInvoicePaidResponse, error)
	CancelInvoice(context.Context, *CancelInvoiceRequest) (*CancelInvoiceResponse, error)
	// ==================== Credit Notes ====================
	CreateCreditNote(context.Context, *CreateCreditNoteRequest) (*CreateCreditNoteResponse, error)
	GetCreditNote(context.Context, *GetCreditNoteRequest) (*GetCreditNoteResponse, error)
	ListCreditNotes(context.Context, *ListCreditNotesRequest) (*ListCreditNotesResponse, error)
	SendCreditNote(context.Context, *SendCreditNoteRequest) (*SendCreditNoteResponse, error)
	// ==================== Payments ====================
	RecordPayment(context.Context, *RecordPaymentRequest) (*RecordPaymentResponse, error)
	ListPayments(context.Context, *ListPaymentsRequest) (*ListPaymentsResponse, error)
	DeletePayment(context.Context, *DeletePaymentRequest) (*DeletePaymentResponse, error)
	// ==================== Dunning ====================
	ListDunnings(context.Context, *ListDunningsRequest) (*ListDunningsResponse, error)
	CreateDunning(context.Context, *CreateDunningRequest) (*CreateDunningResponse, error)
	SendDunning(context.Context, *SendDunningRequest) (*SendDunningResponse, error)
	EscalateDunning(context.Context, *EscalateDunningRequest) (*EscalateDunningResponse, error)
	GetDunningConfig(context.Context, *GetDunningConfigRequest) (*GetDunningConfigResponse, error)
	UpdateDunningConfig(context.Context, *UpdateDunningConfigRequest) (*UpdateDunningConfigResponse, error)
	// Open items (Offene Posten): the receivables the dunning run escalates.
	ListOpenItems(context.Context, *ListOpenItemsRequest) (*ListOpenItemsResponse, error)
	// ==================== Dashboard ====================
	GetFinanceDashboard(context.Context, *GetFinanceDashboardRequest) (*GetFinanceDashboardResponse, error)
	// ==================== DATEV Export ====================
	ExportDATEV(context.Context, *ExportDATEVRequest) (*ExportDATEVResponse, error)
	// ==================== PDF Generation ====================
	GenerateQuotePDF(context.Context, *GenerateQuotePDFRequest) (*GenerateQuotePDFResponse, error)
	GenerateInvoicePDF(context.Context, *GenerateInvoicePDFRequest) (*GenerateInvoicePDFResponse, error)
	GenerateCreditNotePDF(context.Context, *GenerateCreditNotePDFRequest) (*GenerateCreditNotePDFResponse, error)
	GenerateDunningPDF(context.Context, *GenerateDunningPDFRequest) (*GenerateDunningPDFResponse, error)
	GenerateZUGFeRDInvoicePDF(context.Context, *GenerateZUGFeRDInvoicePDFRequest) (*GenerateZUGFeRDInvoicePDFResponse, error)
	GenerateEInvoice(context.Context, *GenerateEInvoiceRequest) (*GenerateEInvoiceResponse, error)
	// ==================== Time-Tracking → Invoice ====================
	CreateInvoiceFromTimeEntries(context.Context, *CreateInvoiceFromTimeEntriesRequest) (*CreateInvoiceFromTimeEntriesResponse, error)
	// ==================== Deal-to-Quote ====================
	CreateQuoteFromDeal(context.Context, *CreateQuoteFromDealRequest) (*CreateQuoteFromDealResponse, error)
	// ==================== GoBD Journal & Compliance ====================
	GetJournalSummary(context.Context, *GetJournalSummaryRequest) (*GetJournalSummaryResponse, error)
	ValidateInvoiceNumber(context.Context, *ValidateInvoiceNumberRequest) (*ValidateInvoiceNumberResponse, error)
	LockInvoice(context.Context, *LockInvoiceRequest) (*LockInvoiceResponse, error)
	// ==================== Payment Statistics ====================
	GetPaymentStats(context.Context, *GetPaymentStatsRequest) (*GetPaymentStatsResponse, error)
	// ==================== Dunning Gaps ====================
	UpdateDunningStatus(context.Context, *UpdateDunningStatusRequest) (*UpdateDunningStatusResponse, error)
	SendDunningNotice(context.Context, *SendDunningNoticeRequest) (*SendDunningNoticeResponse, error)
	// ==================== GoBD Export ====================
	GenerateGoBDExport(context.Context, *GenerateGoBDExportRequest) (*GenerateGoBDExportResponse, error)
	// ==================== GoBD Belegarchiv (§147 AO) ====================
	ArchiveDocument(context.Context, *ArchiveDocumentRequest) (*ArchiveDocumentResponse, error)
	ArchiveInvoiceDocument(context.Context, *ArchiveInvoiceDocumentRequest) (*ArchiveInvoiceDocumentResponse, error)
	GetGobdDocument(context.Context, *GetGobdDocumentRequest) (*GetGobdDocumentResponse, error)
	ListGobdDocuments(context.Context, *ListGobdDocumentsRequest) (*ListGobdDocumentsResponse, error)
	DownloadGobdDocument(context.Context, *DownloadGobdDocumentRequest) (*DownloadGobdDocumentResponse, error)
	AddDocumentAnnotation(context.Context, *AddDocumentAnnotationRequest) (*AddDocumentAnnotationResponse, error)
	// ==================== Incoming Invoices (E-Rechnung Eingang) ====================
	ImportIncomingInvoice(context.Context, *ImportIncomingInvoiceRequest) (*ImportIncomingInvoiceResponse, error)
	GetIncomingInvoice(context.Context, *GetIncomingInvoiceRequest) (*GetIncomingInvoiceResponse, error)
	ListIncomingInvoices(context.Context, *ListIncomingInvoicesRequest) (*ListIncomingInvoicesResponse, error)
	UpdateIncomingInvoiceStatus(context.Context, *UpdateIncomingInvoiceStatusRequest) (*UpdateIncomingInvoiceStatusResponse, error)
	// ==================== Recurring Invoices (Abo-Rechnungen) ====================
	CreateRecurringInvoice(context.Context, *CreateRecurringInvoiceRequest) (*CreateRecurringInvoiceResponse, error)
	GetRecurringInvoice(context.Context, *GetRecurringInvoiceRequest) (*GetRecurringInvoiceResponse, error)
	ListRecurringInvoices(context.Context, *ListRecurringInvoicesRequest) (*ListRecurringInvoicesResponse, error)
	UpdateRecurringInvoice(context.Context, *UpdateRecurringInvoiceRequest) (*UpdateRecurringInvoiceResponse, error)
	DeleteRecurringInvoice(context.Context, *DeleteRecurringInvoiceRequest) (*DeleteRecurringInvoiceResponse, error)
	SetRecurringInvoiceStatus(context.Context, *SetRecurringInvoiceStatusRequest) (*SetRecurringInvoiceStatusResponse, error)
	GenerateRecurringInvoice(context.Context, *GenerateRecurringInvoiceRequest) (*GenerateRecurringInvoiceResponse, error)
	// ==================== Bank Statements (Zahlungsabgleich) ====================
	ImportBankStatement(context.Context, *ImportBankStatementRequest) (*ImportBankStatementResponse, error)
	GetBankStatement(context.Context, *GetBankStatementRequest) (*GetBankStatementResponse, error)
	ListBankStatements(context.Context, *ListBankStatementsRequest) (*ListBankStatementsResponse, error)
	ListBankTransactions(context.Context, *ListBankTransactionsRequest) (*ListBankTransactionsResponse, error)
	ReconcileBankTransaction(context.Context, *ReconcileBankTransactionRequest) (*ReconcileBankTransactionResponse, error)
	IgnoreBankTransaction(context.Context, *IgnoreBankTransactionRequest) (*IgnoreBankTransactionResponse, error)
	// ==================== Expenses (Ausgaben) ====================
	CreateExpense(context.Context, *CreateExpenseRequest) (*CreateExpenseResponse, error)
	ListExpenses(context.Context, *ListExpensesRequest) (*ListExpensesResponse, error)
	UpdateExpense(context.Context, *UpdateExpenseRequest) (*UpdateExpenseResponse, error)
	DeleteExpense(context.Context, *DeleteExpenseRequest) (*DeleteExpenseResponse, error)
	DecideExpense(context.Context, *DecideExpenseRequest) (*DecideExpenseResponse, error)
	AttachExpenseReceipt(context.Context, *AttachExpenseReceiptRequest) (*AttachExpenseReceiptResponse, error)
	mustEmbedUnimplementedFinanceServiceServer()
}

